// Temporary in-memory observer of real engine frames; no runtime effect component.
using System;using System.IO;using System.Linq;using System.Collections.Generic;
using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class BlueWispLiveQA {
 static string Out=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/BlueWisp/V3");
 static GameObject clone;static ParticleSystem[] systems;static List<object> samples=new List<object>();static HashSet<int> captured=new HashSet<int>();static int stage,frame=-1,zeroFrames,activeFrames,drained,restored,reused;static double begin;static bool background;static EditorWindow focused;static float[] pausedAges;
 static float Age(ParticleSystem p){var a=new ParticleSystem.Particle[1];return p.GetParticles(a)>0?a[0].startLifetime-a[0].remainingLifetime:-1;}
 static object State(ParticleSystem p){float age=Age(p);return new{p.name,p.time,count=p.particleCount,age,pose=age<0?-1:Mathf.Min(3,Mathf.FloorToInt(age/.07f)),emission=p.emission.enabled,paused=p.isPaused};}
 static void Sample(string label){samples.Add(new{label,frame=Time.frameCount,time=Time.timeAsDouble,systems=systems.Select(State).ToArray()});}
 static void Capture(int pose){var cg=new GameObject("BlueWisp_LiveCamera");RenderTexture rt=null;var old=RenderTexture.active;try{var cam=cg.AddComponent<Camera>();cam.enabled=false;cam.orthographic=true;cam.orthographicSize=2.5f;cam.transform.position=new Vector3(0,0,-10);cam.cullingMask=1<<31;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(69/255f,69/255f,69/255f);cam.allowHDR=false;cam.allowMSAA=false;rt=new RenderTexture(600,500,24);rt.Create();cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var t=new Texture2D(600,500,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,600,500),0,0);t.Apply();File.WriteAllBytes(Path.Combine(Out,"Live_Pose"+(pose+1)+".png"),t.EncodeToPNG());UnityEngine.Object.Destroy(t);}finally{RenderTexture.active=old;if(rt!=null){rt.Release();UnityEngine.Object.Destroy(rt);}UnityEngine.Object.Destroy(cg);}}
 static void Finish(string error=null){EditorApplication.update-=Tick;if(clone!=null)UnityEngine.Object.Destroy(clone);Application.runInBackground=background;if(focused!=null)focused.Focus();var report=new{success=error==null&&captured.Count==4&&drained==0&&restored==2&&reused==2&&zeroFrames==0,error,method="Actual Play Mode / advancing native particle ages; four live renders; Emission drain/restore, per-system Pause/Play, Stop/Play, root enable and offscreen return. No Simulate/Emit/SetParticles.",capturedPoses=captured.OrderBy(x=>x),activeFrames,zeroFrames,drained,restored,reused,samples,settingsRestored=true};File.WriteAllText(Path.Combine(Out,"LivePlayback.json"),JsonConvert.SerializeObject(report,Formatting.Indented));}
 static void Tick(){try{
  if(!Application.isPlaying){Finish("Stopped externally");return;}if(Time.frameCount==frame)return;frame=Time.frameCount;double elapsed=Time.timeAsDouble-begin;
  if(stage==0){float age=Age(systems[0]);if(age>=0){int pose=Mathf.Min(3,Mathf.FloorToInt(age/.07f));if(age% .07f>.012f&&age% .07f<.058f&&captured.Add(pose)){Sample("live_pose_"+pose);Capture(pose);}}if(elapsed>.1){activeFrames++;if(systems.Any(p=>p.particleCount!=1))zeroFrames++;}if(elapsed>1.7){Sample("steady_loops");foreach(var p in systems){var e=p.emission;e.enabled=false;}stage=1;begin=Time.timeAsDouble;}}
  else if(stage==1&&elapsed>.5){drained=systems.Sum(p=>p.particleCount);Sample("emission_drained");foreach(var p in systems){var e=p.emission;e.enabled=true;}stage=2;begin=Time.timeAsDouble;}
  else if(stage==2&&elapsed>.5){restored=systems.Sum(p=>p.particleCount);Sample("emission_restored");pausedAges=systems.Select(Age).ToArray();foreach(var p in systems)p.Pause(false);stage=3;begin=Time.timeAsDouble;}
  else if(stage==3&&elapsed>.2){if(systems.Select(Age).Where((a,i)=>Mathf.Abs(a-pausedAges[i])>1e-5f).Any())throw new Exception("Particle pause did not hold shader clock");Sample("native_pause_held");foreach(var p in systems)p.Play(false);stage=4;begin=Time.timeAsDouble;}
  else if(stage==4&&elapsed>.18){Sample("native_resume");foreach(var p in systems){p.Stop(false,ParticleSystemStopBehavior.StopEmittingAndClear);p.Play(false);}stage=5;begin=Time.timeAsDouble;}
  else if(stage==5&&elapsed>.04){Sample("native_restart");clone.SetActive(false);stage=6;begin=Time.timeAsDouble;}
  else if(stage==6&&elapsed>.1){clone.SetActive(true);stage=7;begin=Time.timeAsDouble;}
  else if(stage==7&&elapsed>.12){reused=systems.Sum(p=>p.particleCount);Sample("root_reuse");clone.transform.position=Vector3.right*100;stage=8;begin=Time.timeAsDouble;}
  else if(stage==8&&elapsed>.2){clone.transform.position=Vector3.zero;Sample("offscreen_return");Finish();}
 }catch(Exception e){Finish(e.ToString());}}
 public static string Run(){if(!Application.isPlaying||Application.dataPath!="/Users/user/Desktop/VFXDemo/VFXDemo/Assets"||SceneManager.GetActiveScene().path!="Assets/Scenes/VFXWorkbench.unity")throw new Exception("Wrong target/state");background=Application.runInBackground;Application.runInBackground=true;focused=EditorWindow.focusedWindow;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();clone=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PixelFX/BlueWisp/V3/Prefabs/VFX_BlueWisp_V3_Loop.prefab"));clone.name="BlueWisp_LiveQA_Temporary";foreach(var t in clone.GetComponentsInChildren<Transform>())t.gameObject.layer=31;systems=clone.GetComponentsInChildren<ParticleSystem>();foreach(var p in systems){p.Stop(false,ParticleSystemStopBehavior.StopEmittingAndClear);p.Play(false);}begin=Time.timeAsDouble;EditorApplication.update+=Tick;return "Native playback observation started (~4 engine seconds).";}
}
